                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/minha-conta"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <MinhaContaPage />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/funcionarios/:id"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <FuncionarioPerfil />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/freelancers"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <FreelancersPage />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    {/* Ouvidoria — painel das donas (gate owner-only feito internamente via useOuvidoriaAccess) */}
                    <Route
                      path="/ouvidoria"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <OuvidoriaPage />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/ouvidoria/:id"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <OuvidoriaDetalhePage />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/separacao/:requisicaoId"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <PaginaPicking />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />
                    <Route
                      path="/configuracoes"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <Configuracoes />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />


                    <Route
                      path="/gerenciar-produtos"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <GerenciarProdutosMasterPage />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/producao/fichas-tecnicas"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <FichasTecnicas />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />
                    <Route
                      path="/producao/fichas-tecnicas/configurador"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <RecipeConfigurator />
                        </PermissionProtectedRoute>
                      }
                    />
                    <Route
                      path="/producao/insumos"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <Insumos />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />
                    <Route
                      path="/admin"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <AdminDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/atendimento-virtual"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <AtendimentoVirtual />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    {/* Painel TV (Torre de Controle): com sidebar normal */}
                    <Route
                      path="/tv"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <TvDashboardPage />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/tv/metas"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <TvMetasPage />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    {/* Drill-down por unidade da Torre de Controle (navegação
                        interna — sem item próprio na sidebar) */}
                    <Route
                      path="/tv/loja/:id"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <TvStoreDetailPage />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    {/* Gestão Operacional N1 — 3 rotas explícitas (D5 ADR) */}
                    <Route
                      path="/gestao/logistica"
                      element={
                        <PermissionProtectedRoute requiredPermission="view_gestao_logistica">
                          <DashboardLayout>
                            <GestaoSetorPage setor="logistica" />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />
                    <Route
                      path="/gestao/producao"
                      element={
                        <PermissionProtectedRoute requiredPermission="view_gestao_producao">
                          <DashboardLayout>
                            <GestaoSetorPage setor="producao" />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />
                    <Route
                      path="/gestao/estoque"
                      element={
                        <PermissionProtectedRoute requiredPermission="view_gestao_estoque">
                          <DashboardLayout>
                            <GestaoSetorPage setor="estoque" />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia"
                      element={
                        <ProtectedRoute>
                          <DashboardLayout>
                            <MiaInlineChat />
                          </DashboardLayout>
                        </ProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/outcomes"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaOutcomesDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/health"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaHealthDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/patterns"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaPatternsDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/improve"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaImproveDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route
                      path="/mia/observability"
                      element={
                        <PermissionProtectedRoute adminOnly={true}>
                          <DashboardLayout>
                            <MiaObservabilityDashboard />
                          </DashboardLayout>
                        </PermissionProtectedRoute>
                      }
                    />

                    <Route path="*" element={<NotFound />} />

                  </Routes>
                  </MiaProvider>
                </StoreProvider>
              </PermissionsProvider>
            </AuthProvider>
          </BrowserRouter>
        </TooltipProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
};

export default App;

